{
  "query": "query GetChannels { channels(input: { organizationId: \"YOUR_BUFFER_ORGANIZATION_ID\" }) { id name displayName service } }"
}

={{ JSON.stringify({
  query: `mutation CreatePost {
    createPost(
      input: {
        text: ${JSON.stringify($('Post creator').first().json.output.replace(/\*\*/g, ''))}
        channelId: "YOUR_BUFFER_CHANNEL_ID"
        schedulingType: automatic
        mode: addToQueue
        saveToDraft: false
        assets: [
          {
            image: {
              url: ${JSON.stringify($('imageUrl1').first().json.imageUrl)}
            }
          }
          {
            image: {
              url: ${JSON.stringify($('fieldImageUrl').first().json.fieldImageUrl)}
            }
          }
          {
            image: {
              url: ${JSON.stringify($json.secure_url)}
            }
          }
        ]
      }
    ) {
      ... on PostActionSuccess {
        post {
          id
          text
          assets {
            id
            mimeType
          }
        }
      }
      ... on MutationError {
        message
      }
    }
  }`
}) }}

